def rng(v,d=1):return f(min(v),d)+' to '+f(max(v),d) if v else '--'
def sl(v,d=1):return '/'.join(f(x,d) for x in v)
def gain(ci,obj):return record(REF[ci],'P3',obj)['objective_value']-record(REF[ci],'P0',obj)['objective_value']
